-- Riferimento storico (da database/schema.sql, schema SQLite eliminato con la migrazione).
-- Schema iniziale dell'applicazione, creato da Flyway alla prima partenza.

CREATE TABLE "utenti" (
    "id_utente"      BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "nome_utente"    VARCHAR(100) NOT NULL,
    "password"       VARCHAR(100) NOT NULL,
    "email"          VARCHAR(255) NOT NULL,
    "amministratore" BOOLEAN NOT NULL DEFAULT FALSE,
    CONSTRAINT "un_utenti_nome_utente" UNIQUE ("nome_utente")
);

-- Tabella tecnica del mutex applicativo: la riga permanente id=1 è presa con
-- SELECT ... FOR UPDATE nella stessa transazione che verifica le invarianti
-- amministrative e scrive (design D5).
CREATE TABLE "app_lock" (
    "id"          BIGINT NOT NULL PRIMARY KEY,
    "descrizione" VARCHAR(255)
);

INSERT INTO "app_lock" ("id", "descrizione") VALUES (1, 'mutex applicativo');
